WITH filtered AS (SELECT *, LOWER(status) status_lower, COALESCE(channel, 'DIRECT') channel_clean FROM orders WHERE order_date >= DATE '2023-03-29'), with_windows AS (SELECT id, customer_id, store_id, order_date, amount, discount, channel_clean, CORR(amount, discount) OVER (PARTITION BY customer_id) corr_amount_discount, LAG(discount, 1) OVER (PARTITION BY customer_id, channel ORDER BY discount, id) prev_discount, SUM(amount) OVER (ORDER BY discount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_amount, AVG(discount) OVER (PARTITION BY channel ORDER BY order_date, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) discount_avg_5, COUNT(discount) OVER (PARTITION BY customer_id) customer_id_count_discount FROM filtered), with_dims AS (SELECT a.id, a.customer_id, a.store_id, a.order_date, a.amount, a.discount, a.channel_clean, a.corr_amount_discount, a.discount_avg_5, a.customer_id_count_discount, p.city, p.name FROM with_windows a LEFT JOIN customers p ON a.customer_id <=> p.id), with_window AS (SELECT e.*, sub.id AS subscription_id, sub.plan, sub.monthly_fee FROM with_dims e LEFT JOIN subscriptions sub ON e.customer_id = sub.customer_id AND e.order_date >= sub.start_date AND e.order_date < sub.end_date + INTERVAL 30 DAYS), not_flagged AS (SELECT s.* FROM with_window s WHERE NOT EXISTS (SELECT 1 FROM shipments x WHERE x.order_id = s.id AND x.shipped_date >= s.order_date)) SELECT id, customer_id, store_id, order_date, amount, discount, channel_clean, corr_amount_discount, discount_avg_5 FROM not_flagged
